":"Timeline"}]},{"t":"p","r":[{"x":"From Q1 2025 to Q1 2026. The country lead starts in the first quarter."}]},{"t":"h2","r":[{"x":"Risks"}]},{"t":"ul","li":[[{"x":"Hiring the country lead takes longer than planned."}],[{"x":"Clients prefer a local firm."}]]}],"saved_by":"PR","saved_on":"2024-06-03","note":"First full draft","extra":null,"sort":1},{"id":"DC-1:v3","document_id":"DC-1","version":3,"title":"Nordics market entry: brief","body":[{"t":"h2","r":[{"x":"Purpose"}]},{"t":"p","r":[{"x":"Open a Nordic office with a local country lead and win our first three Nordic clients, so that new markets reach the revenue share in our strategy."}]},{"t":"h2","r":[{"x":"Background"}]},{"t":"p","r":[{"x":"Two of our largest clients run Nordic subsidiaries and ask for local support. The market survey found strong demand for delivery and data services in Norway and Sweden."}]},{"t":"h2","r":[{"x":"Scope"}]},{"t":"ul","li":[[{"x":"In: a small office in Oslo, a country lead, two consultants and a local partner network."}],[{"x":"Out: Denmark and Finland until the first year is reviewed."}]]},{"t":"h2","r":[{"x":"Success measures"}]},{"t":"ul","li":[[{"x":"Nordic prospects in active talks: 4 by the end of the first year."}],[{"x":"Revenue from new markets: up to 15% of revenue."}]]},{"t":"h2","r":[{"x":"Timeline"}]},{"t":"p","r":[{"x":"From Q1 2025 to Q1 2026. The country lead starts in the first quarter."}]},{"t":"h3","r":[{"x":"Hiring the country lead"}]},{"t":"ol","li":[[{"x":"Brief two search firms in October."}],[{"x":"Shortlist by the end of November."}],[{"x":"Offer before the Christmas break."}]]},{"t":"h2","r":[{"x":"Risks"}]},{"t":"ul","li":[[{"x":"Hiring the country lead takes longer than planned: we start the search before the decision."}],[{"x":"Clients prefer a local firm: we partner with a local network for the first year."}]]}],"saved_by":"PR","saved_on":"2024-06-12","note":"Added how we hire the country lead","extra":null,"sort":2},{"id":"DC-2:v1","document_id":"DC-2","version":1,"title":"Nordics market entry: business case","body":[{"t":"h2","r":[{"x":"Summary"}]},{"t":"p","r":[{"x":"We ask for £1.2M to open a Nordic office from Q1 2025."}]},{"t":"h2","r":[{"x":"The problem"}]},{"t":"p","r":[{"x":"What is wrong today, and what it costs us."}]},{"t":"h2","r":[{"x":"Options"}]},{"t":"p","r":[{"x":"The options we looked at, including doing nothing."}]},{"t":"h2","r":[{"x":"Recommended option"}]},{"t":"p","r":[{"x":"The option we recommend, and why."}]},{"t":"h2","r":[{"x":"Costs and benefits"}]},{"t":"p","r":[{"x":"What it costs, when, and the benefits we expect."}]},{"t":"h2","r":[{"x":"Risks"}]},{"t":"p","r":[{"x":"What could go wrong, and how we reduce it."}]},{"t":"h2","r":[{"x":"Decision needed"}]},{"t":"p","r":[{"x":"Who decides, and by when."}]}],"saved_by":"PR","saved_on":"2024-08-19","note":"Started from the business case template","extra":null,"sort":0},{"id":"DC-2:v2","document_id":"DC-2","version":2,"title":"Nordics market entry: business case","body":[{"t":"h2","r":[{"x":"Summary"}]},{"t":"p","r":[{"x":"We ask the steering group for "},{"x":"£1.2M over two years","b":true},{"x":" to open a Nordic office from Q1 2025, with a country lead and two consultants."}]},{"t":"h2","r":[{"x":"The problem"}]},{"t":"p","r":[{"x":"Nordic subsidiaries of our clients buy delivery and data services from local firms because we have nobody there. We lose about four bids a year."}]},{"t":"h2","r":[{"x":"Options"}]},{"t":"ol","li":[[{"x":"A. Do nothing: ","b":true},{"x":"keep serving Nordic work from London."}],[{"x":"B. Partner only: ","b":true},{"x":"sell through a local partner network."}],[{"x":"C. Open an office in Oslo: ","b":true},{"x":"a country lead, two consultants and a partner network."}]]},{"t":"h2","r":[{"x":"Recommended option"}]},{"t":"p","r":[{"x":"Option C. The market survey shows enough demand, and two clients have asked for local support."}]},{"t":"h2","r":[{"x":"Costs and benefits"}]},{"t":"p","r":[{"x":"The office costs £1.2M over two years, mostly people. We expect to break even in the third year and to reach 15% of revenue from new markets."}]},{"t":"p","r":[{"x":"Survey results and the cash profile are on the "},{"x":"market survey page","a":"https://intranet.example.com/nordics/survey"},{"x":"."}]},{"t":"h2","r":[{"x":"Risks"}]},{"t":"ul","li":[[{"x":"Hiring the country lead takes longer than planned."}],[{"x":"Exchange rates move against us."}],[{"x":"The partner network wins work we wanted."}]]},{"t":"h2","r":[{"x":"Decision needed"}]},{"t":"p","r":[{"x":"The steering group decides at the Q3 2024 review (decision D-14)."}]}],"saved_by":"PR","saved_on":"2024-09-10","note":"Options, costs and risks written","extra":null,"sort":1},{"id":"DC-3:v1","document_id":"DC-3","version":1,"title":"Q2 2024 review: meeting notes","body":[{"t":"h2","r":[{"x":"Attendees"}]},{"t":"ul","li":[[{"x":"Dianne Miles (chair)"}],[{"x":"Paul Reyes"}],[{"x":"Marta Lindqvist"}],[{"x":"Jonas Keller"}],[{"x":"Dana Nowak"}],[{"x":"Liza Martines"}],[{"x":"Olivia Adams (minutes)"}]]},{"t":"h2","r":[{"x":"Decisions"}]},{"t":"ul","li":[[{"x":"D-12: extend the market survey by three weeks (approved)."}],[{"x":"D-13: fund a second vendor to build courses (rejected)."}]]},{"t":"h2","r":[{"x":"Actions"}]},{"t":"p","r":[{"x":"Who does what, by when."}]},{"t":"h2","r":[{"x":"Notes"}]},{"t":"p","r":[{"x":"Recurring revenue and client retention stay on the agenda as the main exceptions."}]}],"saved_by":"OA","saved_on":"2024-07-15","note":"Notes taken in the meeting","extra":null,"sort":0},{"id":"DC-3:v2","document_id":"DC-3","version":2,"title":"Q2 2024 review: meeting notes","body":[{"t":"h2","r":[{"x":"Attendees"}]},{"t":"ul","li":[[{"x":"Dianne Miles (chair)"}],[{"x":"Paul Reyes"}],[{"x":"Marta Lindqvist"}],[{"x":"Jonas Keller"}],[{"x":"Dana Nowak"}],[{"x":"Liza Martines"}],[{"x":"Olivia Adams (minutes)"}]]},{"t":"h2","r":[{"x":"Decisions"}]},{"t":"ul","li":[[{"x":"D-12: extend the market survey by three weeks (approved)."}],[{"x":"D-13: fund a second vendor to build courses (rejected). Technology brings a revised plan with internal trainers."}]]},{"t":"h2","r":[{"x":"Actions"}]},{"t":"ul","li":[[{"x":"Paul Reyes shares the Nordic hiring plan before the Q3 review."}],[{"x":"Olivia Adams sends the minutes and actions to every attendee."}],[{"x":"Olivia Adams adds the unit check-in deadlines to the governance calendar."}]]},{"t":"h2","r":[{"x":"Notes"}]},{"t":"p","r":[{"x":"Recurring revenue and client retention stay on the agenda as the main exceptions."}]}],"saved_by":"OA","saved_on":"2024-07-16","note":"Added the actions","extra":null,"sort":1},{"id":"DC-4:v1","document_id":"DC-4","version":1,"title":"Client health checks: brief","body":[{"t":"h2","r":[{"x":"Purpose"}]},{"t":"p","r":[{"x":"Run a health check with every key client, so we see churn coming and agree a recovery plan in time."}]},{"t":"h2","r":[{"x":"Background"}]},{"t":"p","r":[{"x":"What has happened so far, and what we already know."}]},{"t":"h2","r":[{"x":"Scope"}]},{"t":"p","r":[{"x":"What is in, and what is out."}]},{"t":"h2","r":[{"x":"Success measures"}]},{"t":"ul","li":[[{"x":"Key clients with a health check: 40 by the end of the year."}]]},{"t":"h2","r":[{"x":"Timeline"}]},{"t":"p","r":[{"x":"The main steps and their dates."}]},{"t":"h2","r":[{"x":"Risks"}]},{"t":"p","r":[{"x":"What could stop us, and what we do about it."}]}],"saved_by":"ML","saved_on":"2024-09-02","note":"Started from the brief template","extra":null,"sort":0},{"id":"DC-4:v2","document_id":"DC-4","version":2,"title":"Client health checks: brief","body":[{"t":"h2","r":[{"x":"Purpose"}]},{"t":"p","r":[{"x":"Run a health check with every key client, so we see churn coming and agree a recovery plan in time."}]},{"t":"h2","r":[{"x":"Background"}]},{"t":"p","r":[{"x":"Client retention is just below target. Most clients we lost last year showed warning signs months earlier: fewer meetings, late payments and a new sponsor."}]},{"t":"h2","r":[{"x":"Scope"}]},{"t":"ul","li":[[{"x":"In: the top 40 clients by revenue, a standard health score and a named follow-up owner."}],[{"x":"Out: smaller clients, who keep the yearly survey."}]]},{"t":"h2","r":[{"x":"Success measures"}]},{"t":"ul","li":[[{"x":"Key clients with a health check: 40 by the end of the year."}],[{"x":"At-risk clients with a recovery plan: all of them, within two weeks of the check."}]]},{"t":"h2","r":[{"x":"Timeline"}]},{"t":"p","r":[{"x":"Checks run from October to December, ten clients a month, with the results in the Q4 review."}]},{"t":"h2","r":[{"x":"Risks"}]},{"t":"ul","li":[[{"x":"Account leads are too busy: the client success team books and runs the checks."}],[{"x":"Scores differ between teams: one scoring guide and a calibration session."}]]}],"saved_by":"ML","saved_on":"2024-09-13","note":"Scope, timeline and risks written","extra":null,"sort":1},{"id":"DC-5:v1","document_id":"DC-5","version":1,"title":"Shared data platform: business case","body":[{"t":"h2","r":[{"x":"Summary"}]},{"t":"p","r":[{"x":"We ask for £950k to bring finance, delivery and client data onto one shared platform."}]},{"t":"h2","r":[{"x":"The problem"}]},{"t":"p","r":[{"x":"Finance and delivery report from separate spreadsheets. Month-end reconciliation takes four days and the numbers still disagree."}]},{"t":"h2","r":[{"x":"Options"}]},{"t":"p","r":[{"x":"The options we looked at, including doing nothing."}]},{"t":"h2","r":[{"x":"Recommended option"}]},{"t":"p","r":[{"x":"The option we recommend, and why."}]},{"t":"h2","r":[{"x":"Costs and benefits"}]},{"t":"p","r":[{"x":"What it costs, when, and the benefits we expect."}]},{"t":"h2","r":[{"x":"Risks"}]},{"t":"p","r":[{"x":"What could go wrong, and how we reduce it."}]},{"t":"h2","r":[{"x":"Decision needed"}]},{"t":"p","r":[{"x":"Who decides, and by when."}]}],"saved_by":"JK","saved_on":"2024-09-05","note":"Summary and problem written","extra":null,"sort":0},{"id":"DC-6:v1","document_id":"DC-6","version":1,"title":"Educational platform: course review notes","body":[{"t":"h2","r":[{"x":"Attendees"}]},{"t":"ul","li":[[{"x":"Jonas Keller"}],[{"x":"Dana Nowak"}],[{"x":"Olivia Adams"}]]},{"t":"h2","r":[{"x":"Decisions"}]},{"t":"ul","li":[[{"x":"Courses 1 to 6 are ready for the accessibility check."}],[{"x":"Courses 7 to 10 wait for internal trainers."}]]},{"t":"h2","r":[{"x":"Actions"}]},{"t":"ul","li":[[{"x":"Dana Nowak books the accessibility check for courses 1 to 6."}],[{"x":"Jonas Keller asks the practice leads for two trainers until December."}]]},{"t":"h2","r":[{"x":"Notes"}]},{"t":"p","r":[{"x":"Learners asked for shorter videos. The next courses keep each video under eight minutes."}]}],"saved_by":"JK","saved_on":"2024-08-28","note":"Notes from the course review","extra":null,"sort":0}]$r5a1d42$::jsonb)
