12","approved_on":"2024-06-14","approved_by":"DM","extra":null,"sort":0},{"id":"DC-2","kind":"case","title":"Nordics market entry: business case","status":"review","owner_id":"PR","approver_id":"DM","initiative_id":"I7","project_id":null,"meeting_id":null,"body":[{"t":"h2","r":[{"x":"Summary"}]},{"t":"p","r":[{"x":"We ask the steering group for "},{"x":"£1.2M over two years","b":true},{"x":" to open a Nordic office from Q1 2025, with a country lead and two consultants."}]},{"t":"h2","r":[{"x":"The problem"}]},{"t":"p","r":[{"x":"Nordic subsidiaries of our clients buy delivery and data services from local firms because we have nobody there. We lose about four bids a year."}]},{"t":"h2","r":[{"x":"Options"}]},{"t":"ol","li":[[{"x":"A. Do nothing: ","b":true},{"x":"keep serving Nordic work from London."}],[{"x":"B. Partner only: ","b":true},{"x":"sell through a local partner network."}],[{"x":"C. Open an office in Oslo: ","b":true},{"x":"a country lead, two consultants and a partner network."}]]},{"t":"h2","r":[{"x":"Recommended option"}]},{"t":"p","r":[{"x":"Option C. The market survey shows enough demand, and two clients have asked for local support."}]},{"t":"h2","r":[{"x":"Costs and benefits"}]},{"t":"p","r":[{"x":"The office costs £1.2M over two years, mostly people. We expect to break even in the third year and to reach 15% of revenue from new markets."}]},{"t":"p","r":[{"x":"Survey results and the cash profile are on the "},{"x":"market survey page","a":"https://intranet.example.com/nordics/survey"},{"x":"."}]},{"t":"h2","r":[{"x":"Risks"}]},{"t":"ul","li":[[{"x":"Hiring the country lead takes longer than planned."}],[{"x":"Exchange rates move against us."}],[{"x":"The partner network wins work we wanted."}]]},{"t":"h2","r":[{"x":"Decision needed"}]},{"t":"p","r":[{"x":"The steering group decides at the Q3 2024 review (decision D-14)."}]}],"created_on":"2024-08-19","updated_on":"2024-09-10","submitted_on":"2024-09-10","approved_on":null,"approved_by":null,"extra":null,"sort":1},{"id":"DC-3","kind":"notes","title":"Q2 2024 review: meeting notes","status":"approved","owner_id":"OA","approver_id":"DM","initiative_id":null,"project_id":null,"meeting_id":"RM1","body":[{"t":"h2","r":[{"x":"Attendees"}]},{"t":"ul","li":[[{"x":"Dianne Miles (chair)"}],[{"x":"Paul Reyes"}],[{"x":"Marta Lindqvist"}],[{"x":"Jonas Keller"}],[{"x":"Dana Nowak"}],[{"x":"Liza Martines"}],[{"x":"Olivia Adams (minutes)"}]]},{"t":"h2","r":[{"x":"Decisions"}]},{"t":"ul","li":[[{"x":"D-12: extend the market survey by three weeks (approved)."}],[{"x":"D-13: fund a second vendor to build courses (rejected). Technology brings a revised plan with internal trainers."}]]},{"t":"h2","r":[{"x":"Actions"}]},{"t":"ul","li":[[{"x":"Paul Reyes shares the Nordic hiring plan before the Q3 review."}],[{"x":"Olivia Adams sends the minutes and actions to every attendee."}],[{"x":"Olivia Adams adds the unit check-in deadlines to the governance calendar."}]]},{"t":"h2","r":[{"x":"Notes"}]},{"t":"p","r":[{"x":"Recurring revenue and client retention stay on the agenda as the main exceptions."}]}],"created_on":"2024-07-15","updated_on":"2024-07-16","submitted_on":"2024-07-16","approved_on":"2024-07-17","approved_by":"DM","extra":null,"sort":2},{"id":"DC-4","kind":"brief","title":"Client health checks: brief","status":"review","owner_id":"ML","approver_id":"OA","initiative_id":"I5","project_id":null,"meeting_id":null,"body":[{"t":"h2","r":[{"x":"Purpose"}]},{"t":"p","r":[{"x":"Run a health check with every key client, so we see churn coming and agree a recovery plan in time."}]},{"t":"h2","r":[{"x":"Background"}]},{"t":"p","r":[{"x":"Client retention is just below target. Most clients we lost last year showed warning signs months earlier: fewer meetings, late payments and a new sponsor."}]},{"t":"h2","r":[{"x":"Scope"}]},{"t":"ul","li":[[{"x":"In: the top 40 clients by revenue, a standard health score and a named follow-up owner."}],[{"x":"Out: smaller clients, who keep the yearly survey."}]]},{"t":"h2","r":[{"x":"Success measures"}]},{"t":"ul","li":[[{"x":"Key clients with a health check: 40 by the end of the year."}],[{"x":"At-risk clients with a recovery plan: all of them, within two weeks of the check."}]]},{"t":"h2","r":[{"x":"Timeline"}]},{"t":"p","r":[{"x":"Checks run from October to December, ten clients a month, with the results in the Q4 review."}]},{"t":"h2","r":[{"x":"Risks"}]},{"t":"ul","li":[[{"x":"Account leads are too busy: the client success team books and runs the checks."}],[{"x":"Scores differ between teams: one scoring guide and a calibration session."}]]}],"created_on":"2024-09-02","updated_on":"2024-09-13","submitted_on":"2024-09-13","approved_on":null,"approved_by":null,"extra":null,"sort":3},{"id":"DC-5","kind":"case","title":"Shared data platform: business case","status":"draft","owner_id":"JK","approver_id":"LM","initiative_id":"I8","project_id":null,"meeting_id":null,"body":[{"t":"h2","r":[{"x":"Summary"}]},{"t":"p","r":[{"x":"We ask for £950k to bring finance, delivery and client data onto one shared platform."}]},{"t":"h2","r":[{"x":"The problem"}]},{"t":"p","r":[{"x":"Finance and delivery report from separate spreadsheets. Month-end reconciliation takes four days and the numbers still disagree."}]},{"t":"h2","r":[{"x":"Options"}]},{"t":"p","r":[{"x":"The options we looked at, including doing nothing."}]},{"t":"h2","r":[{"x":"Recommended option"}]},{"t":"p","r":[{"x":"The option we recommend, and why."}]},{"t":"h2","r":[{"x":"Costs and benefits"}]},{"t":"p","r":[{"x":"What it costs, when, and the benefits we expect."}]},{"t":"h2","r":[{"x":"Risks"}]},{"t":"p","r":[{"x":"What could go wrong, and how we reduce it."}]},{"t":"h2","r":[{"x":"Decision needed"}]},{"t":"p","r":[{"x":"Who decides, and by when."}]}],"created_on":"2024-09-05","updated_on":"2024-09-05","submitted_on":null,"approved_on":null,"approved_by":null,"extra":null,"sort":4},{"id":"DC-6","kind":"notes","title":"Educational platform: course review notes","status":"approved","owner_id":"JK","approver_id":"DN","initiative_id":null,"project_id":"P2","meeting_id":null,"body":[{"t":"h2","r":[{"x":"Attendees"}]},{"t":"ul","li":[[{"x":"Jonas Keller"}],[{"x":"Dana Nowak"}],[{"x":"Olivia Adams"}]]},{"t":"h2","r":[{"x":"Decisions"}]},{"t":"ul","li":[[{"x":"Courses 1 to 6 are ready for the accessibility check."}],[{"x":"Courses 7 to 10 wait for internal trainers."}]]},{"t":"h2","r":[{"x":"Actions"}]},{"t":"ul","li":[[{"x":"Dana Nowak books the accessibility check for courses 1 to 6."}],[{"x":"Jonas Keller asks the practice leads for two trainers until December."}]]},{"t":"h2","r":[{"x":"Notes"}]},{"t":"p","r":[{"x":"Learners asked for shorter videos. The next courses keep each video under eight minutes."}]}],"created_on":"2024-08-28","updated_on":"2024-08-28","submitted_on":"2024-08-28","approved_on":"2024-08-30","approved_by":"DN","extra":null,"sort":5}]$r6jjoiq$::jsonb)
